(()=>{'use strict';
const BASE=structuredClone(window.BASE_DATA||{}),SAVE_KEY='ramisa_v7_content',PAGES=['home','works','background','perspective','contact'];
const id=()=>Math.random().toString(36).slice(2,9),clone=x=>structuredClone(x),$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),attr=esc;
const safeSrc=x=>{const s=String(x||'');return /^(https?:\/\/|assets\/|\.\/assets\/|data:image\/|data:video\/|blob:)/.test(s)?s:''};
const clamp=(v,a,b,d=a)=>Number.isFinite(+v)?Math.max(a,Math.min(b,+v)):d;
const swatch=[['#ffb597','#d879d4','#a8bfed'],['#a1e8d7','#9195f0','#ecc1d2'],['#fce08e','#f19ab6','#a7d0e1'],['#b797fa','#f5a1c9','#97e9de']];
const block=(type='text')=>({id:id(),type,html:type==='text'?'<p>Write here. Click to edit.</p>':'',src:'',width:640,height:360,orientation:'landscape',fontSize:17,color:'',underline:false,bold:false});
const section=(type='custom',title='New section')=>({id:id(),type,title,body:'Write your story here.',width:100,height:0,padding:65,titleSize:48,bodySize:16,color:'',background:'',titleUnderline:false,blocks:[]});
const defaultSections={home:[section('hero','Introduction'),section('facts','Highlights'),section('featured','Featured work'),section('summary','Professional summary'),section('articleStack','Perspective highlights')],works:[section('worksGrid','Selected work')],background:[section('degrees','Education'),section('experience','Experience'),section('skills','Skills & capabilities')],perspective:[section('articleGallery','Articles & perspectives')],contact:[section('contact','Contact')]};
function initState(){let from={};try{from=JSON.parse(localStorage.getItem(SAVE_KEY))||{}}catch{}let obj={...BASE,...(window.PORTFOLIO_CONTENT||{}),...from};obj.settings={heroSize:88,sectionSize:58,bodySize:16,navSize:13,characterSize:110,characterVisible:true,backgroundOpacity:35,backgroundSpeed:22,backgroundDirection:45,backgroundMotion:true,cursorSize:38,cursorOpacity:70,theme:'light',signature:'',signatureWidth:200,heroHeight:560,featuredArticles:[],...(obj.settings||{})};obj.sections??=clone(defaultSections);if(obj.sections.education&&!obj.sections.background){obj.sections.background=obj.sections.education;delete obj.sections.education;}for(const p of PAGES)if(!Array.isArray(obj.sections[p]))obj.sections[p]=clone(defaultSections[p]);obj.works??=clone(BASE.works||[]);obj.articles??=clone(BASE.articles||[]);obj.works.forEach((w,i)=>{w.id??=id();w.cover??={type:'image',src:'',width:700,height:360};w.tileHeight??=i===0?430:340;w.tileSpan??=1;w.tileWidthPx??=0;w.orientation??='landscape';w.media??=[]});obj.articles.forEach((a,i)=>{a.id??=id();a.cover??={type:'image',src:'',width:620,height:380};a.columns??=1;a.blocks??=[];a.featured??=(i===0);a.isOriginal??=false});return obj}
let state=initState(),editing=false,undoStack=[],mediaURLs=new Map(),selectedPage='home',currentArticle=null,objectDB;
function notify(msg){let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.style.cssText='position:fixed;z-index:200;bottom:25px;left:50%;transform:translateX(-50%);background:#29212f;color:white;padding:13px 23px;border-radius:12px;box-shadow:0 10px 40px #0004;max-width:90%;font:600 13px Urbanist,Arial';document.body.append(el)}el.textContent=msg;clearTimeout(notify._t);notify._t=setTimeout(()=>el.remove(),3300)}
function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch{notify('Browser storage is full. Use Publish ZIP to preserve your changes.') }}
function snap(){undoStack.push(JSON.stringify(state));if(undoStack.length>20)undoStack.shift()}
function update(fn,{rerender=true}={}){snap();fn();persist();if(rerender)render()}
function dbOpen(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(new Error('Browser media storage unavailable'));const req=indexedDB.open('ramisa_portfolio_uploads_v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'path'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbPut(path,file){return new Promise(async(resolve,reject)=>{try{const db=objectDB||await dbOpen();objectDB=db;const t=db.transaction('files','readwrite');t.objectStore('files').put({path,blob:file});t.oncomplete=resolve;t.onerror=()=>reject(t.error)}catch(e){reject(e)}})}
function dbAll(){return new Promise(async(resolve,reject)=>{try{const db=objectDB||await dbOpen();objectDB=db;const t=db.transaction('files','readonly'),r=t.objectStore('files').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}catch(e){reject(e)}})}
async function hydrate(){try{const rows=await dbAll();rows.forEach(x=>mediaURLs.set(x.path,URL.createObjectURL(x.blob)));render()}catch(e){console.warn('Media storage unavailable',e.message)}}
function mediaSrc(path){return mediaURLs.get(path)||safeSrc(path)}
async function upload(file){if(!file)return '';const ext=(file.name.split('.').pop()||'bin').replace(/[^a-z0-9]/gi,'').toLowerCase().slice(0,8)||'bin';const path=`assets/uploads/${Date.now()}-${id()}.${ext}`;await dbPut(path,file);mediaURLs.set(path,URL.createObjectURL(file));return path}
let pickerResolve=null;function pick(accept='image/*,video/*,application/pdf,.docx,.doc'){return new Promise(resolve=>{const inp=$('#filePicker');inp.value='';inp.accept=accept;pickerResolve=resolve;inp.click()})}
$('#filePicker').addEventListener('change',e=>{const f=e.target.files?.[0]||null;pickerResolve?.(f);pickerResolve=null});
function textOf(s){return String(s||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim()}
function mediaHTML(m,css=''){const src=mediaSrc(m.src||'');const w=clamp(m.width,80,2500,640),h=clamp(m.height,80,1600,360),sty=`width:min(100%,${w}px);height:${h}px;${css}`;if(!src)return `<div class="media-zone">No media selected. Use Edit to upload an image, video, or PDF.</div>`;if(m.type==='video')return `<video class="inline-media" style="${sty}" src="${attr(src)}" playsinline muted controls preload="metadata"></video>`;if(m.type==='pdf')return `<div class="pdf-wrapper"><iframe style="${sty}" src="${attr(src)}" title="PDF attachment"></iframe><a href="${attr(src)}" target="_blank" rel="noopener">Open PDF ↗</a></div>`;return `<img class="inline-media" style="${sty}" src="${attr(src)}" alt="Portfolio media" loading="lazy">`}
function coverHTML(m,visual,title){const src=mediaSrc(m?.src||'');if(!src)return `<span class="ring"></span><span class="letters">${esc(visual)}</span>`;return m.type==='video'?`<video src="${attr(src)}" muted autoplay loop playsinline preload="metadata" aria-label="${attr(title)} cover video"></video>`:`<img src="${attr(src)}" alt="${attr(title)} cover" loading="lazy">`}
function mascot(){return `<div class="mascot" aria-label="Pastel Shape-Shifter character" role="img"><svg viewBox="0 0 110 145" aria-hidden="true"><defs><linearGradient id="mgrad" x1=".2" y1=".1" x2=".8" y2="1"><stop stop-color="#ffec9c"/><stop offset=".38" stop-color="#a1ebd3"/><stop offset=".72" stop-color="#d4a2f2"/><stop offset="1" stop-color="#ff80b8"/></linearGradient></defs><ellipse cx="55" cy="137" rx="32" ry="6" fill="#a58ac8" opacity=".18"/><ellipse cx="24" cy="87" rx="14" ry="23" fill="#c6a4ee" transform="rotate(-22 24 87)"/><ellipse cx="87" cy="80" rx="14" ry="24" fill="#ffa0c9" transform="rotate(-28 87 80)"/><rect x="28" y="109" width="19" height="26" rx="10" fill="#c5a3f3"/><rect x="62" y="109" width="19" height="26" rx="10" fill="#f69bcd"/><rect x="21" y="15" width="68" height="111" rx="34" fill="url(#mgrad)"/><ellipse cx="34" cy="85" rx="7" ry="3" fill="#ff93b5" opacity=".48"/><ellipse cx="79" cy="85" rx="7" ry="3" fill="#ff93b5" opacity=".48"/><g class="mascot-eyes"><ellipse cx="43" cy="67" rx="5.8" ry="8.4" fill="#392443"/><ellipse cx="69" cy="67" rx="5.8" ry="8.4" fill="#392443"/><circle cx="44.8" cy="64" r="2.2" fill="#fff"/><circle cx="70.8" cy="64" r="2.2" fill="#fff"/></g><path d="M47 85 Q55 97 63 85" stroke="#a74d7f" stroke-width="3.4" fill="none" stroke-linecap="round"/><path d="M89 25l6-7M93 35l8-2" stroke="#ffc45f" stroke-width="2.5" stroke-linecap="round"/></svg></div>`}

function tools(page,index){if(!editing)return '';return `<div class="edit-handle"><button data-action="edit-section" data-page="${page}" data-i="${index}">✎ Edit</button><button data-action="section-up" data-page="${page}" data-i="${index}" title="Move up">↑</button><button data-action="section-down" data-page="${page}" data-i="${index}" title="Move down">↓</button><button data-action="duplicate-section" data-page="${page}" data-i="${index}">⧉</button><button data-action="delete-section" data-page="${page}" data-i="${index}">×</button></div>`}
function projectCard(w,i,small=false){const colors=w.colors||swatch[i%swatch.length];return `<article class="project-card" data-action="open-work" data-i="${i}" data-span="${small?1:clamp(w.tileSpan,1,2,1)}" style="${!small&&w.tileWidthPx?`max-width:${clamp(w.tileWidthPx,180,1400,620)}px`:``}" tabindex="0" role="link"><div class="project-cover" style="--c1:${attr(colors[0])};--c2:${attr(colors[1])};--c3:${attr(colors[2])};--tile-height:${small?210:w.orientation==='portrait'?Math.max(clamp(w.tileHeight,140,850,350),520):w.orientation==='square'?Math.max(clamp(w.tileHeight,140,850,350),360):clamp(w.tileHeight,140,850,350)}px">${coverHTML(w.cover,w.visual||'W',w.title)}</div><div class="project-caption"><div><small>${esc(w.category)} / ${esc(w.brand)}</small><h3>${esc(w.title)}</h3></div><span class="arrow">↗</span></div></article>`}
function artCard(a,i,featured=false){const color=swatch[i%swatch.length];return `<article class="article-card ${featured?'featured':''}" tabindex="0" data-action="open-article" data-i="${i}"><div class="article-cover" style="background:radial-gradient(at 15% 22%,${color[0]},transparent 64%),radial-gradient(at 80% 75%,${color[1]},transparent 70%),${color[2]}">${coverHTML(a.cover,(a.title||'Article').split(' ').slice(0,2).join(' '),a.title)}</div><div class="article-desc"><small>${esc(a.source||'Original writing')}</small><h3>${esc(a.title)}</h3></div></article>`}
function homeHero(){return `<div class="hero"><div class="hero-copy"><div class="eyebrow">A little about me ✳</div><h1>${esc(state.name?.split(' ').slice(0,2).join(' ')||'Ramisa Rahman')}<span class="gradient-word" style="display:block">${esc(state.name?.split(' ').slice(2).join(' ')||'Shitu')}</span></h1><p>${esc(state.tagline)}</p><p class="hero-summary">${esc(state.role)} · Brand strategy, creative direction and human-centered storytelling.</p><div class="btn-row"><a class="primary-btn" href="#works">Explore my work ↗</a><a class="ghost-btn" href="#contact">Let’s connect ↗</a></div></div><div class="hero-side"><div class="hero-scene"><div class="orb"></div><div class="orbit"></div><div class="small-orb"></div>${state.settings.characterVisible?mascot():''}</div></div></div>`}
function articleStack(){const ids=state.settings.featuredArticles?.length?state.settings.featuredArticles:state.articles.slice(0,3).map(a=>a.id);const chosen=ids.map(id=>state.articles.find(a=>a.id===id)).filter(Boolean).slice(0,3);return `<div class="section-head"><div><div class="eyebrow">02 / Perspectives</div><h2>Thoughts worth <span class="gradient-word">sharing.</span></h2><p>Ideas and writing on brands, communication and culture.</p></div><a href="#perspective" class="ghost-btn">All articles ↗</a></div><div class="home-editorials">${chosen.map(a=>{const i=state.articles.indexOf(a);return `<article class="home-editorial" tabindex="0" data-action="open-article" data-i="${i}"><div class="home-editorial-cover">${coverHTML(a.cover,'',a.title)}</div><div class="home-editorial-label"><span>${esc(a.source||'Original writing')}</span><strong>${esc(a.title)}</strong><span aria-hidden="true">↗</span></div></article>`}).join('')}</div>${editing?'<div class="btn-row"><button class="ghost-btn" data-action="select-stack">Select homepage articles</button></div>':''}`}

function renderSection(s,page,index){let html='';switch(s.type){case 'hero':html=homeHero();break;case 'facts':html=`<div class="fact-grid"><div class="fact"><strong>83M+</strong><small>Views on Art of Plating S2</small></div><div class="fact"><strong>Bronze</strong><small>COMMWARD · Creative Strategy</small></div><div class="fact"><strong>2024–Now</strong><small>Akij Tableware · Brand Custodian</small></div></div>`;break;case 'featured':html=`<div class="section-head"><div><div class="eyebrow">01 / selected work</div><h2>Work that <span class="gradient-word">speaks.</span></h2></div><a href="#works" class="ghost-btn">View all projects ↗</a></div><div class="featured-projects">${state.works.slice(0,3).map((w,i)=>projectCard(w,i,true)).join('')}</div>`;break;case 'summary':html=`<div class="section-head"><div><div class="eyebrow">About me</div><h2>At the intersection of<br><span class="gradient-word">strategy & creativity.</span></h2></div></div><p class="module-text" style="max-width:860px">${esc(state.summary)}</p>`;break;case 'articleStack':html=articleStack();break;case 'worksGrid':html=`<div class="page-head"><div class="eyebrow">01 / selected work</div><h1>Work that <span class="gradient-word">speaks.</span></h1><p>Campaigns, experiences and brand moments shaped with purpose.</p></div><div class="project-grid">${state.works.map((w,i)=>projectCard(w,i)).join('')}</div>${editing?'<div class="btn-row"><button class="ghost-btn" data-action="manage-works">Manage work covers and sizes</button><button class="ghost-btn" data-action="new-work">+ New project</button></div>':''}`;break;case 'degrees':html=`<div class="section-head"><h2>Academic journey<span class="gradient-word">.</span></h2></div><div class="timeline">${state.education.map(x=>`<div class="edu-card"><span class="eyebrow">${esc(x.year)}</span><h3>${esc(x.degree)}</h3><p>${esc(x.subject)}</p><b>${esc(x.score)}</b></div>`).join('')}</div>`;break;case 'experience':html=`<div class="section-head"><h2>Professional experience<span class="gradient-word">.</span></h2></div><div class="timeline">${state.experience.map(x=>`<div class="edu-card"><span class="eyebrow">${esc(x.year)}</span><h3>${esc(x.title)}</h3><p>${esc(x.company)}</p></div>`).join('')}</div>`;break;case 'skills':html=`<h2>Skills & strengths</h2><div class="tagcloud">${state.skills.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`;break;case 'articleGallery':{const chosen=state.articles.findIndex(x=>x.featured);const n=chosen<0?0:chosen;html=`<div class="page-head"><div class="eyebrow">02 / stories & perspectives</div><h1>Stories, ideas, <span class="gradient-word">perspectives.</span></h1><p>A collection of original thoughts, published articles and ideas that explore creativity, marketing and culture.</p></div><div class="magazine-feature">${state.articles.length?`<div class="magazine-feature-cover" data-action="open-article" data-i="${n}" tabindex="0">${coverHTML(state.articles[n].cover,'',state.articles[n].title)}</div><div class="magazine-feature-copy"><div class="eyebrow">Featured perspective / ${esc(state.articles[n].source||'Original writing')}</div><h2>${esc(state.articles[n].title)}</h2><p>A selected perspective from my writing archive. Explore the article, or browse the other pieces below.</p><button class="primary-btn" data-action="open-article" data-i="${n}">Read featured article ↗</button></div>`:''}</div><div class="magazine-heading"><div><div class="eyebrow">The reading shelf</div><h2>Explore the archive<span class="gradient-word">.</span></h2></div><span class="reading-hint">Swipe to explore →</span></div><div class="magazine-shelf">${state.articles.map((a,i)=>`<article class="magazine-issue" data-action="open-article" data-i="${i}" tabindex="0"><div class="magazine-issue-cover" style="--issue-a:${swatch[i%4][0]};--issue-b:${swatch[i%4][1]}">${coverHTML(a.cover,'',a.title)}</div><div class="magazine-issue-info"><small>${esc(a.source||'Original writing')}</small><strong>${esc(a.title)}</strong></div></article>`).join('')}</div>${editing?'<div class="btn-row"><button class="ghost-btn" data-action="manage-articles">Choose featured article & covers</button><button class="ghost-btn" data-action="new-article">+ Compose new article</button></div>':''}`;break}case 'contact':html=`<div class="page-head"><div class="eyebrow">Let's connect</div><h1>Let's make something<br><span class="gradient-word">meaningful.</span></h1><p>For collaborations, projects and conversations, feel free to get in touch.</p></div><div class="btn-row"><a class="primary-btn" href="mailto:${attr(state.email)}">${esc(state.email)} ↗</a><a class="ghost-btn" target="_blank" rel="noopener" href="${attr(state.linkedin)}">LinkedIn ↗</a></div><div style="position:relative;min-height:140px">${state.settings.characterVisible?mascot():''}</div>`;break;default:html=`<h2>${esc(s.title||'New section')}</h2><p class="module-text">${esc(s.body||'')}</p>`}
if(s.blocks?.length){html+=`<div class="custom-content">${s.blocks.map(b=>`<div>${b.type==='text'?`<div class="article-text" style="font-size:${clamp(b.fontSize,10,100,16)}px;color:${esc(b.color||'inherit')};text-decoration:${b.underline?'underline':'none'}">${b.html||''}</div>`:mediaHTML(b)}</div>`).join('')}</div>`}
const style=`min-height:${clamp(s.height,0,1700,0)}px;padding:${clamp(s.padding,0,200,65)}px 0;background:${/^(#[0-9a-f]{6}|transparent)$/i.test(s.background)?s.background:'transparent'};`;return `<section class="module" data-section="${s.id}" draggable="${editing}" style="${style}"><div class="module-content container" style="width:min(calc(100% - 2 * var(--page-gutter)),${clamp(s.width,35,100,100)}%,1290px);color:${/^#[0-9a-f]{6}$/i.test(s.color)?s.color:'inherit'}"><div style="${s.titleUnderline?'text-decoration:underline':''};--section-size:${clamp(s.titleSize,18,160,54)}px;--body-size:${clamp(s.bodySize,11,70,16)}px">${html}</div></div>${tools(page,index)}</section>`}
function pageTemplate(page){const parts=(state.sections[page]||[]).map((s,i)=>renderSection(s,page,i)).join('');return `<div class="page container-page">${parts}${editing?`<section class="container" style="padding:20px 0 80px"><button class="add-block-btn" data-action="add-section" data-page="${page}">+ Add a section to this page</button></section>`:''}</div>`}
function casePage(i){const w=state.works[i];if(!w)return pageTemplate('works');const colors=w.colors||swatch[0];return `<div class="container page"><div class="case-hero"><div><a class="eyebrow" href="#works">← Back to all work</a><h1>${esc(w.title)}</h1><p>${esc(w.subtitle||'')}</p><div class="tagcloud"><span>${esc(w.brand)}</span><span>${esc(w.category)}</span></div></div><div class="case-visual"><div class="project-cover" style="--c1:${colors[0]};--c2:${colors[1]};--c3:${colors[2]}">${coverHTML(w.cover,w.visual||'W',w.title)}</div></div></div><div class="case-body"><div><div class="eyebrow">My role</div><h2>${esc(w.role||'Campaign')}</h2></div><div><h2>Project overview</h2><p>${esc(w.description||'')}</p><h3>Impact</h3><p>${esc(w.outcome||'')}</p></div></div><div class="case-assets">${(w.media||[]).map(x=>mediaHTML(x)).join('')}</div>${editing?`<div class="btn-row"><button class="ghost-btn" data-action="edit-work" data-i="${i}">✎ Edit this case study, cover & media</button></div>`:''}</div>`}
function articleBlockHTML(b,ai,bi){const columns=clamp(b.columns,1,3,1),cols=b.items||Array.from({length:columns},()=>[block()]);while(cols.length<columns)cols.push([block()]);return `<section class="article-block" data-ai="${ai}" data-bi="${bi}">${editing?`<div class="article-section-actions"><button class="mini-btn" data-action="article-block-up" data-ai="${ai}" data-bi="${bi}">↑ Move</button><button class="mini-btn" data-action="article-block-down" data-ai="${ai}" data-bi="${bi}">↓ Move</button><button class="mini-btn" data-action="article-cols" data-ai="${ai}" data-bi="${bi}">Columns: ${columns} ▾</button><button class="mini-btn" data-action="article-block-remove" data-ai="${ai}" data-bi="${bi}">× Remove section</button></div>`:''}<div class="article-columns" style="--cols:${columns}">${cols.slice(0,columns).map((items,ci)=>`<div class="article-column ${editing?'editable':''}" data-col="${ci}">${items.map((item,ii)=>articleItemHTML(item,ai,bi,ci,ii)).join('')}${editing?`<button class="mini-btn" data-action="add-article-item" data-ai="${ai}" data-bi="${bi}" data-ci="${ci}">+ Text / image / video / PDF</button>`:''}</div>`).join('')}</div></section>`}
function articleItemHTML(b,ai,bi,ci,ii){const pos=`data-ai="${ai}" data-bi="${bi}" data-ci="${ci}" data-ii="${ii}"`;const cmds=editing?`<div class="content-toolbar"><button class="mini-btn" data-action="format-item" ${pos}>⚙ Style</button>${b.type==='text'?`<button class="mini-btn" data-action="rich-bold" ${pos} title="Bold selected text"><b>B</b></button><button class="mini-btn" data-action="rich-underline" ${pos} title="Underline selected text"><u>U</u></button><button class="mini-btn" data-action="rich-italic" ${pos} title="Italic selected text"><i>I</i></button>`:''}${b.type!=='text'?`<button class="mini-btn" data-action="change-item-file" ${pos}>Upload/replace</button>`:''}<button class="mini-btn" data-action="move-item-up" ${pos}>↑</button><button class="mini-btn" data-action="move-item-down" ${pos}>↓</button><button class="mini-btn" data-action="remove-item" ${pos}>×</button></div>`:'';return `<div class="article-element" ${pos}>${cmds}${b.type==='text'?`<div class="article-text" style="font-size:${clamp(b.fontSize,11,90,17)}px;color:${/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'inherit'};text-decoration:${b.underline?'underline':'none'};font-weight:${b.bold?'700':'400'}" ${editing?'contenteditable="true" data-action="inline-edit"':''}>${b.html||'<p>Write your paragraph here.</p>'}</div>`:mediaHTML(b)}</div>`}
function articlePage(i){const a=state.articles[i];if(!a)return pageTemplate('perspective');return `<div class="page article-reading container"><header><a class="eyebrow" href="#perspective">← Back to perspective</a><h1 ${editing?'contenteditable="true" data-article-title="'+i+'"':''}>${esc(a.title)}</h1><p class="eyebrow">${esc(a.source||'Original writing')}</p>${a.url?`<a href="${attr(a.url)}" target="_blank" rel="noopener" class="ghost-btn">View original publication ↗</a>`:''}${editing?`<div class="btn-row" style="justify-content:center"><button class="ghost-btn" data-action="article-settings" data-i="${i}">✎ Article settings & cover</button><button class="ghost-btn" data-action="article-import" data-i="${i}">Import PDF or DOCX</button></div>`:''}</header>${a.cover?.src?`<div class="article-hero-media">${mediaHTML(a.cover)}</div>`:''}<div class="article-blocks">${a.blocks.map((b,bi)=>articleBlockHTML(b,i,bi)).join('')}${editing?`<button class="add-block-btn" data-action="article-block-add" data-i="${i}">+ Add article section</button>`:''}</div></div>`}
function render(){const hash=decodeURIComponent(location.hash.slice(1)||'home').replace(/^education(?=\/|$)/,'background'),[page,part]=hash.split('/');selectedPage=PAGES.includes(page)?page:'home';const html=page==='works'&&part?casePage(state.works.findIndex(w=>w.id===part)):page==='perspective'&&part?articlePage(state.articles.findIndex(a=>a.id===part)):pageTemplate(selectedPage);$('#app').innerHTML=html;document.body.classList.toggle('editing',editing);$('#editToolbar').hidden=!editing;$('#editBtn').textContent=editing?'✓ Finish editing':'✳ Edit site';document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+selectedPage));$('#brandName').textContent=state.name;$('#brandPortrait').innerHTML=state.photo?`<img src="${attr(mediaSrc(state.photo))}" alt="Ramisa profile">`:'';$('#footer').innerHTML=`<div>${state.settings.signature?`<img class="signature" src="${attr(mediaSrc(state.settings.signature))}" alt="Ramisa signature" style="width:${clamp(state.settings.signatureWidth,40,550,200)}px">`:`<span class="footer-name">${esc(state.name)}</span>`}<small>Creating with curiosity, care & a little color.</small></div><div><a href="${attr(state.linkedin)}" target="_blank" rel="noopener">LinkedIn ↗</a><a href="mailto:${attr(state.email)}">Email ↗</a><small>© ${new Date().getFullYear()}</small></div>`;applyStyle()}
function applyStyle(){const v=state.settings;document.body.classList.toggle('dark',v.theme==='dark');document.body.classList.toggle('motion-off',v.backgroundMotion===false);const root=document.documentElement;for(const [key,val] of Object.entries({'--hero-height':`${clamp(v.heroHeight,250,1100,560)}px`,'--hero-size':`${clamp(v.heroSize,28,170,88)}px`,'--section-size':`${clamp(v.sectionSize,24,130,58)}px`,'--body-size':`${clamp(v.bodySize,11,28,16)}px`,'--nav-size':`${clamp(v.navSize,10,22,13)}px`,'--mascot-size':`${clamp(v.characterSize,40,280,110)}px`,'--grad-opacity':clamp(v.backgroundOpacity,0,100,35)/100,'--grad-speed':`${clamp(v.backgroundSpeed,5,90,22)}s`,'--grad-direction':`${clamp(v.backgroundDirection,0,360,45)}deg`,'--cursor-size':`${clamp(v.cursorSize,10,130,38)}px`,'--cursor-opacity':clamp(v.cursorOpacity,0,100,70)/100}))root.style.setProperty(key,val)}
const locationItem=(ai,bi,ci,ii)=>state.articles[ai]?.blocks[bi]?.items[ci]?.[ii];
function input(name,value,type='text',extra=''){if(type==='textarea')return `<div class="field ${extra}"><label>${name}</label><textarea data-field="${attr(name)}">${esc(value)}</textarea></div>`;if(type==='checkbox')return `<div class="field ${extra}"><label><input type="checkbox" data-field="${attr(name)}" ${value?'checked':''}> ${name}</label></div>`;return `<div class="field ${extra}"><label>${name}</label><input data-field="${attr(name)}" type="${type}" value="${attr(value??'')}"></div>`}
function select(name,choices,value){return `<div class="field"><label>${name}</label><select data-field="${attr(name)}">${choices.map(([v,l])=>`<option value="${attr(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function modal(title,body,onSave,{buttons='',width='690px'}={}){const layer=$('#modalLayer');layer.hidden=false;layer.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${attr(title)}" style="max-width:${width}"><div class="modal-head"><h2>${esc(title)}</h2><button class="mini-btn" data-close>✕</button></div><div>${body}</div><div class="modal-footer"><button class="primary-btn" id="modalSave">Apply changes</button><button class="ghost-btn" data-close>Cancel</button>${buttons}</div></section>`;layer.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModal));layer.onclick=e=>{if(e.target===layer)closeModal()};$('#modalSave').onclick=async()=>{const values={};layer.querySelectorAll('[data-field]').forEach(el=>values[el.dataset.field]=el.type==='checkbox'?el.checked:el.value);try{await onSave(values,layer);closeModal();render()}catch(e){notify('Could not save: '+e.message)}}}
function closeModal(){$('#modalLayer').hidden=true;$('#modalLayer').innerHTML=''}
async function selectMedia(target,allowed='image/*,video/*,application/pdf'){const f=await pick(allowed);if(!f)return null;const type=f.type.startsWith('image/')?'image':f.type.startsWith('video/')?'video':f.type==='application/pdf'?'pdf':'';if(!type){notify('Choose an image, video, or PDF.');return null}try{return {type,src:await upload(f),width:target?.width||640,height:target?.height||360}}catch(e){notify('Upload failed: '+e.message);return null}}
function basicMediaFields(obj){return `${select('Media type',[['image','Image'],['video','Video'],['pdf','PDF']],obj?.type||'image')}${input('File path',obj?.src||'')}${input('Width (px)',obj?.width||640,'number')}${input('Height (px)',obj?.height||360,'number')}<div class="field wide"><button class="ghost-btn" id="modalUpload" type="button">↑ Choose image / video / PDF</button><p class="tip">Files are stored in your browser for editing and included when you download the Publish ZIP.</p></div>`}
function bindModalUpload(obj,allowed='image/*,video/*,application/pdf'){const btn=$('#modalUpload');if(btn)btn.onclick=async()=>{const m=await selectMedia(obj,allowed);if(!m)return;const form=$('#modalLayer');form.querySelector('[data-field="Media type"]').value=m.type;form.querySelector('[data-field="File path"]').value=m.src;notify('File added; select Apply changes.')};}
function takeMedia(v){return {type:v['Media type'],src:v['File path'],width:clamp(v['Width (px)'],80,2500,640),height:clamp(v['Height (px)'],80,1600,360)}}
function editSection(page,i){const s=state.sections[page]?.[i];if(!s)return;const body=`<div class="form-grid">${input('Section title',s.title)}${input('Width (%)',s.width,'number')}${input('Minimum height (px)',s.height,'number')}${input('Vertical padding (px)',s.padding,'number')}${input('Title font size (px)',s.titleSize,'number')}${input('Body font size (px)',s.bodySize,'number')}${input('Text color (hex)',s.color||'#28212d','color')}${input('Background (hex)',s.background||'#ffffff','color')}${input('Underline title',s.titleUnderline,'checkbox')}${input('Description',s.body,'textarea','wide')}</div><p class="tip">For hero, grid, or article sections, the content uses the section's existing component layout. You can add standalone text, image, video, or PDF blocks to any section.</p><div class="media-actions"><button type="button" class="ghost-btn" id="addSectionMedia">+ Add text / image / video / PDF</button><button type="button" class="ghost-btn" id="editSectionBlocks">Manage added blocks (${s.blocks?.length||0})</button></div>`;modal('Customize section',body,v=>update(()=>{s.title=v['Section title'];s.width=clamp(v['Width (%)'],35,100,100);s.height=clamp(v['Minimum height (px)'],0,1600,0);s.padding=clamp(v['Vertical padding (px)'],0,200,65);s.titleSize=clamp(v['Title font size (px)'],18,150,48);s.bodySize=clamp(v['Body font size (px)'],10,80,16);s.color=v['Text color (hex)'];s.background=v['Background (hex)'];s.titleUnderline=v['Underline title'];s.body=v.Description},{rerender:false}));$('#addSectionMedia').onclick=async()=>{closeModal();chooseSectionBlock(page,i)};$('#editSectionBlocks').onclick=()=>{closeModal();manageSectionBlocks(page,i)}}
function chooseSectionBlock(page,i){const s=state.sections[page][i];modal('Add content to section',`<div class="form-grid">${select('Block type',[['text','Text / heading'],['image','Image'],['video','Video'],['pdf','PDF']],'text')}${input('Width (px)',640,'number')}${input('Height (px)',360,'number')}</div>`,async v=>{const b=block(v['Block type']);b.width=clamp(v['Width (px)'],80,2400,640);b.height=clamp(v['Height (px)'],80,1600,360);if(b.type!=='text'){const m=await selectMedia(b);if(m)Object.assign(b,m)}update(()=>{s.blocks??=[];s.blocks.push(b)},{rerender:false})})}
function manageSectionBlocks(page,i){const s=state.sections[page][i];const body=`${(s.blocks||[]).map((b,j)=>`<div class="edu-card" style="margin:8px 0"><strong>${j+1}. ${esc(b.type)}</strong><div class="media-actions"><button class="mini-btn" data-mb="edit" data-i="${j}">Edit</button><button class="mini-btn" data-mb="up" data-i="${j}">↑</button><button class="mini-btn" data-mb="down" data-i="${j}">↓</button><button class="mini-btn" data-mb="remove" data-i="${j}">×</button></div></div>`).join('')}<button class="ghost-btn" id="moreBlocks">+ Add block</button>`;modal('Section media & text blocks',body,()=>{},{});$('#moreBlocks').onclick=()=>{closeModal();chooseSectionBlock(page,i)};$('#modalLayer').querySelectorAll('[data-mb]').forEach(btn=>btn.onclick=()=>{const j=+btn.dataset.i,action=btn.dataset.mb;if(action==='edit'){closeModal();editGenericBlock(s.blocks[j],()=>manageSectionBlocks(page,i));return}update(()=>{if(action==='remove')s.blocks.splice(j,1);else{const k=j+(action==='up'?-1:1);if(k>=0&&k<s.blocks.length)[s.blocks[j],s.blocks[k]]=[s.blocks[k],s.blocks[j]]}},{rerender:false});closeModal();manageSectionBlocks(page,i)})}
function editGenericBlock(b,back=()=>{}){const body=`<div class="form-grid">${select('Type',[['text','Text'],['image','Image'],['video','Video'],['pdf','PDF']],b.type)}${input('Font size (px)',b.fontSize||17,'number')}${input('Text color',b.color||'#28212d','color')}${input('Underline',b.underline,'checkbox')}${input('Text',textOf(b.html),'textarea','wide')}${basicMediaFields(b)}</div>`;modal('Edit content block',body,v=>{update(()=>{b.type=v.Type;b.fontSize=clamp(v['Font size (px)'],10,100,17);b.color=v['Text color'];b.underline=v.Underline;b.html='<p>'+esc(v.Text)+'</p>';Object.assign(b,takeMedia(v))},{rerender:false});back()});bindModalUpload(b)}
function projectEditor(i){const w=state.works[i];if(!w)return;let body=`<div class="form-grid">${input('Project title',w.title,'text','wide')}${input('Brand',w.brand)}${input('Category',w.category)}${input('Subtitle',w.subtitle,'textarea','wide')}${input('My role',w.role,'textarea','wide')}${input('Overview',w.description,'textarea','wide')}${input('Outcome',w.outcome,'textarea','wide')}${select('Orientation',[['landscape','Landscape'],['portrait','Portrait'],['square','Square']],w.orientation)}${select('Grid span',[['1','One column'],['2','Two columns']],w.tileSpan)}${input('Card height (px)',w.tileHeight,'number')}${input('Card maximum width (px, 0 = auto)',w.tileWidthPx||0,'number')}<div class="field wide"><h3>Cover image / video</h3></div>${basicMediaFields(w.cover)}</div><div class="media-actions"><button class="ghost-btn" id="projectGallery">Manage case-study media (${w.media?.length||0})</button></div>`;modal('Work cover, card and case study',body,v=>update(()=>{Object.assign(w,{title:v['Project title'],brand:v.Brand,category:v.Category,subtitle:v.Subtitle,role:v['My role'],description:v.Overview,outcome:v.Outcome,orientation:v.Orientation,tileSpan:+v['Grid span'],tileHeight:clamp(v['Card height (px)'],140,850,340),tileWidthPx:clamp(v['Card maximum width (px, 0 = auto)'],0,1400,0),cover:takeMedia(v)})},{rerender:false}),{width:'790px'});bindModalUpload(w.cover,'image/*,video/*');$('#projectGallery').onclick=()=>{closeModal();manageProjectMedia(i)}}
function manageProjectMedia(i){const w=state.works[i];const body=`${w.media.map((m,j)=>`<div class="edu-card" style="margin-bottom:8px">${j+1}. ${esc(m.type)} · ${esc(m.src?.split('/').pop()||'not uploaded')} <button class="mini-btn" data-workmedia="edit" data-j="${j}">Edit</button><button class="mini-btn" data-workmedia="delete" data-j="${j}">Delete</button></div>`).join('')}<button class="ghost-btn" id="newWorkMedia">+ Add image / video / PDF</button>`;modal('Case-study media',body,()=>{});$('#newWorkMedia').onclick=async()=>{const m=await selectMedia({width:640,height:360});if(m)update(()=>w.media.push(m),{rerender:false});closeModal();manageProjectMedia(i)};$('#modalLayer').querySelectorAll('[data-workmedia]').forEach(btn=>btn.onclick=()=>{const j=+btn.dataset.j;if(btn.dataset.workmedia==='delete'){update(()=>w.media.splice(j,1),{rerender:false});closeModal();manageProjectMedia(i)}else{closeModal();modal('Edit project media',`<div class="form-grid">${basicMediaFields(w.media[j])}</div>`,v=>update(()=>Object.assign(w.media[j],takeMedia(v)),{rerender:false}));bindModalUpload(w.media[j])}})}
function manageWorks(){const body=state.works.map((w,i)=>`<div class="edu-card" style="margin:8px 0;display:flex;align-items:center;justify-content:space-between;gap:12px"><span><b>${i+1}. ${esc(w.title)}</b><small style="display:block">${esc(w.category)}</small></span><div class="media-actions"><button class="mini-btn" data-workop="edit" data-i="${i}">Edit cover</button><button class="mini-btn" data-workop="up" data-i="${i}">↑</button><button class="mini-btn" data-workop="down" data-i="${i}">↓</button><button class="mini-btn" data-workop="delete" data-i="${i}">×</button></div></div>`).join('')+'<button class="ghost-btn" id="addNewProject">+ Add project</button>';modal('Manage projects & covers',body,()=>{},{width:'790px'});$('#addNewProject').onclick=()=>{update(()=>state.works.push({id:id(),title:'New project',brand:'Brand',category:'Campaign',subtitle:'',role:'',description:'',outcome:'',visual:'NEW',colors:swatch[state.works.length%4],cover:{type:'image',src:'',width:700,height:360},media:[],tileHeight:340,tileSpan:1,tileWidthPx:0,orientation:'landscape'}),{rerender:false});closeModal();projectEditor(state.works.length-1)};$('#modalLayer').querySelectorAll('[data-workop]').forEach(btn=>btn.onclick=()=>{const i=+btn.dataset.i,op=btn.dataset.workop;if(op==='edit'){closeModal();projectEditor(i);return}if(op==='delete'&&!confirm('Delete this project?'))return;update(()=>{if(op==='delete')state.works.splice(i,1);else{const j=i+(op==='up'?-1:1);if(j>=0&&j<state.works.length)[state.works[j],state.works[i]]=[state.works[i],state.works[j]]}},{rerender:false});closeModal();manageWorks()})}
function articleSettings(i){const a=state.articles[i];const body=`<div class="form-grid">${input('Title',a.title,'text','wide')}${input('Publication / category',a.source||'Original writing')}${input('External URL',a.url||'')}${input('Feature on Perspective',a.featured,'checkbox')}${basicMediaFields(a.cover)}</div>`;modal('Article details and cover',body,v=>update(()=>{a.title=v.Title;a.source=v['Publication / category'];a.url=v['External URL'];a.featured=v['Feature on Perspective'];if(a.featured)state.articles.forEach(x=>{if(x!==a)x.featured=false});a.cover=takeMedia(v)},{rerender:false}));bindModalUpload(a.cover,'image/*,video/*')}
function manageArticles(){const body=state.articles.map((a,i)=>`<div class="edu-card" style="margin-bottom:9px;display:flex;align-items:center;justify-content:space-between;gap:9px"><span><b>${esc(a.title)}</b><small style="display:block">${a.featured?'★ FEATURED · ':''}${esc(a.source||'Original')}</small></span><div class="media-actions"><button class="mini-btn" data-artop="feature" data-i="${i}">★</button><button class="mini-btn" data-artop="edit" data-i="${i}">Edit</button><button class="mini-btn" data-artop="open" data-i="${i}">Write</button><button class="mini-btn" data-artop="delete" data-i="${i}">×</button></div></div>`).join('')+'<button id="composeArticle" class="ghost-btn">+ Compose new article</button>';modal('Magazine articles & featured story',body,()=>{},{width:'800px'});$('#composeArticle').onclick=()=>{closeModal();newArticle()};$('#modalLayer').querySelectorAll('[data-artop]').forEach(btn=>btn.onclick=()=>{const i=+btn.dataset.i,op=btn.dataset.artop;if(op==='edit'){closeModal();articleSettings(i)}else if(op==='open'){closeModal();location.hash='#perspective/'+state.articles[i].id}else if(op==='feature'){update(()=>state.articles.forEach((a,j)=>a.featured=j===i),{rerender:false});closeModal();manageArticles()}else if(op==='delete'&&confirm('Delete article?')){update(()=>state.articles.splice(i,1),{rerender:false});closeModal();manageArticles()}})}
function newArticle(){const a={id:id(),title:'New original article',source:'Original writing',url:'',cover:{type:'image',src:'',width:800,height:450},featured:false,isOriginal:true,blocks:[{id:id(),columns:1,items:[[block('text')]]}]};update(()=>state.articles.unshift(a),{rerender:false});location.hash='#perspective/'+a.id;render();notify('Article created. Edit text directly on the page and use + Section to add columns or media.')}
function articleCols(ai,bi){const b=state.articles[ai].blocks[bi];modal('Section columns',`<div class="form-grid">${select('Number of columns',[['1','1 column'],['2','2 columns'],['3','3 columns']],b.columns)}</div><p class="tip">On Android, columns automatically stack vertically for readability.</p>`,v=>update(()=>{b.columns=+v['Number of columns'];b.items??=[];while(b.items.length<b.columns)b.items.push([block()])},{rerender:false}))}
function chooseArticleItem(ai,bi,ci){const b=state.articles[ai].blocks[bi];modal('Add to article column',`<div class="form-grid">${select('Content type',[['text','Text / paragraph'],['image','Image'],['video','Video'],['pdf','PDF']],'text')}${select('Media orientation',[['landscape','Horizontal / landscape'],['portrait','Vertical / portrait'],['square','Square']],'landscape')}</div>`,async v=>{const item=block(v['Content type']);item.orientation=v['Media orientation'];if(item.type!=='text'){const m=await selectMedia(item);if(m)Object.assign(item,m);item.height=item.orientation==='portrait'?530:item.orientation==='square'?400:300}update(()=>b.items[ci].push(item),{rerender:false})})}
function articleItemStyle(ai,bi,ci,ii){const item=locationItem(ai,bi,ci,ii);const body=`<div class="form-grid">${select('Content type',[['text','Text'],['image','Image'],['video','Video'],['pdf','PDF']],item.type)}${input('Font size (px)',item.fontSize||17,'number')}${input('Text color',item.color||'#28212d','color')}${input('Underline',item.underline,'checkbox')}${input('Bold',item.bold,'checkbox')}${select('Media orientation',[['landscape','Horizontal'],['portrait','Vertical'],['square','Square']],item.orientation||'landscape')}${basicMediaFields(item)}</div><p class="tip">Text can be edited directly on the page, including selecting text and applying formatting.</p>`;modal('Format article element',body,v=>update(()=>{item.type=v['Content type'];item.fontSize=clamp(v['Font size (px)'],11,95,17);item.color=v['Text color'];item.underline=v.Underline;item.bold=v.Bold;item.orientation=v['Media orientation'];Object.assign(item,takeMedia(v))},{rerender:false}));bindModalUpload(item)}
function siteSettings(){const s=state.settings;const body=`<h3>Identity</h3><div class="form-grid">${input('Full name',state.name,'text','wide')}${input('Professional role',state.role,'text','wide')}${input('Introduction',state.tagline,'textarea','wide')}${input('Professional summary',state.summary,'textarea','wide')}${input('Email',state.email)}${input('LinkedIn',state.linkedin)}${input('Hero height (px)',s.heroHeight,'number')}${input('Signature width (px)',s.signatureWidth,'number')}</div><div class="media-actions" style="margin-top:12px"><button id="uploadPortrait" class="ghost-btn">↑ Header profile picture</button><button id="uploadSignature" class="ghost-btn">↑ Footer PNG signature</button></div><h3>Font & motion settings</h3><div class="form-grid">${input('Hero font (px)',s.heroSize,'number')}${input('Section font (px)',s.sectionSize,'number')}${input('Body font (px)',s.bodySize,'number')}${input('Navigation font (px)',s.navSize,'number')}${input('Character size (px)',s.characterSize,'number')}${input('Show character',s.characterVisible,'checkbox')}${input('Background opacity (%)',s.backgroundOpacity,'number')}${input('Background speed (seconds)',s.backgroundSpeed,'number')}${input('Background direction (degrees)',s.backgroundDirection,'number')}${input('Enable background animation',s.backgroundMotion,'checkbox')}${input('Cursor size (px)',s.cursorSize,'number')}${input('Cursor opacity (%)',s.cursorOpacity,'number')}</div>`;modal('Identity, typography & animation',body,v=>update(()=>{state.name=v['Full name'];state.role=v['Professional role'];state.tagline=v.Introduction;state.summary=v['Professional summary'];state.email=v.Email;state.linkedin=v.LinkedIn;const keys={'Hero font (px)':'heroSize','Section font (px)':'sectionSize','Body font (px)':'bodySize','Navigation font (px)':'navSize','Character size (px)':'characterSize','Background opacity (%)':'backgroundOpacity','Background speed (seconds)':'backgroundSpeed','Background direction (degrees)':'backgroundDirection','Cursor size (px)':'cursorSize','Cursor opacity (%)':'cursorOpacity','Hero height (px)':'heroHeight','Signature width (px)':'signatureWidth','Show character':'characterVisible','Enable background animation':'backgroundMotion'};for(const [label,key] of Object.entries(keys))s[key]=typeof v[label]==='boolean'?v[label]:Number(v[label])},{rerender:false}));$('#uploadPortrait').onclick=async()=>{const m=await selectMedia({},'image/*');if(m)update(()=>state.photo=m.src,{rerender:false});notify('Profile image added. Close or apply settings.')};$('#uploadSignature').onclick=async()=>{const m=await selectMedia({},'image/png');if(m){update(()=>s.signature=m.src,{rerender:false});notify('Signature added. Close or apply settings.')}}}
function stackSelector(){const set=new Set(state.settings.featuredArticles||[]);const body=state.articles.map(a=>`<label style="display:block;padding:9px"><input type="checkbox" data-stack="${a.id}" ${set.has(a.id)?'checked':''}> ${esc(a.title)}</label>`).join('');modal('Featured homepage articles',body,()=>update(()=>state.settings.featuredArticles=[...$('#modalLayer').querySelectorAll('[data-stack]:checked')].map(x=>x.dataset.stack).slice(0,7),{rerender:false}));}
async function importArticle(ai){const f=await pick('.docx,.pdf,.doc,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document');if(!f)return;const a=state.articles[ai];if(f.name.toLowerCase().endsWith('.docx')){try{const zip=await JSZip.loadAsync(f);const xml=await zip.file('word/document.xml').async('text');const doc=new DOMParser().parseFromString(xml,'application/xml');const ps=[...doc.getElementsByTagName('w:p')].map(p=>[...p.getElementsByTagName('w:t')].map(n=>n.textContent).join('')).filter(Boolean);const html=ps.map(p=>`<p>${esc(p)}</p>`).join('');update(()=>a.blocks.push({id:id(),columns:1,items:[[{...block('text'),html}]]}));notify('DOCX text imported as editable article content. Review formatting and image placement.')}catch(e){notify('DOCX extraction failed: '+e.message)}}else if(f.name.toLowerCase().endsWith('.pdf')){const m=await selectMediaFromFile(f);if(m){update(()=>a.blocks.push({id:id(),columns:1,items:[[m]]}));notify('PDF attached as a viewable document. To edit its text, add a text block and paste or rewrite the content.')}}else notify('For legacy .doc files, save as .docx first for editable import.')}
async function selectMediaFromFile(f){try{const type=f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf')?'pdf':f.type.startsWith('video/')?'video':'image';return {...block(type),src:await upload(f),width:720,height:480}}catch(e){notify(e.message);return null}}
function bindInlineChanges(){document.querySelectorAll('[contenteditable="true"][data-ai]').forEach(el=>el.addEventListener('blur',()=>{const item=locationItem(+el.dataset.ai,+el.dataset.bi,+el.dataset.ci,+el.dataset.ii);if(item){item.html=el.innerHTML;persist()}}));document.querySelectorAll('[data-article-title]').forEach(el=>el.addEventListener('blur',()=>{state.articles[+el.dataset.articleTitle].title=el.textContent.trim();persist()}))}
function beginEdit(){editing=!editing;render();if(editing){notify('Visual editing enabled. Open an article to edit its paragraphs directly.');}else persist()}
async function publish(){persist();notify('Preparing complete GitHub ZIP…');try{const zip=new JSZip();zip.file('index.html',await(await fetch('index.html')).text());zip.file('styles.css',await(await fetch('styles.css')).text());zip.file('app.js',await(await fetch('app.js')).text());zip.file('defaults.js',await(await fetch('defaults.js')).text());zip.file('jszip.min.js',await(await fetch('jszip.min.js')).text());zip.file('content.js','window.PORTFOLIO_CONTENT = '+JSON.stringify(state,null,2)+';\n');const files=await dbAll();for(const x of files)zip.file(x.path,x.blob);zip.file('README.md',`RAMISA RAHMAN SHITU — GITHUB PAGES PORTFOLIO\n\n1. Unzip all files.\n2. Upload all files and the assets folder to the root of a GitHub repository.\n3. Under Settings > Pages, set Deploy from branch: main, root.\n4. Wait for GitHub Pages to publish and open the generated URL.\n\nFor later edits: download the entire site ZIP again from the Edit site toolbar.\nBrowser uploads are stored locally using IndexedDB and are included in Publish ZIP. To edit on a second device, use exported site files; assets are visible, but the original browser file store does not travel, so reuploading changed files on that device may be necessary.\n\nDOCX text extraction imports basic paragraphs; PDF imports attach a PDF for reading, not editable extraction.\nOnline fonts load from Google Fonts. Accessibility: reduced-motion setting is respected.\n`);const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:4}});downloadBlob(blob,'ramisa-github-portfolio-publish.zip');notify('Website package downloaded, including uploaded media.')}catch(e){console.error(e);notify('Export failed ('+e.message+'). Open this site through GitHub Pages or a local server, not file://, then retry.') }}
function downloadBlob(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),20000)}
function onAction(el){const action=el.dataset.action;if(!action)return;const i=+el.dataset.i,page=el.dataset.page||selectedPage,ai=+el.dataset.ai,bi=+el.dataset.bi,ci=+el.dataset.ci,ii=+el.dataset.ii;switch(action){case 'settings':siteSettings();break;case 'export':publish();break;case 'undo':if(undoStack.length){state=JSON.parse(undoStack.pop());persist();render()}break;case 'exit-edit':beginEdit();break;case 'open-work':if(editing){projectEditor(i)}else location.hash='#works/'+state.works[i].id;break;case 'open-article':if(editing){location.hash='#perspective/'+state.articles[i].id}else{let a=state.articles[i];if(a.url&&!a.isOriginal&&!(a.blocks||[]).length){location.hash='#perspective/'+a.id}else location.hash='#perspective/'+a.id}break;case 'edit-work':projectEditor(i);break;case 'manage-works':manageWorks();break;case 'new-work':manageWorks();break;case 'manage-articles':manageArticles();break;case 'new-article':newArticle();break;case 'article-settings':articleSettings(i);break;case 'article-import':importArticle(i);break;case 'select-stack':stackSelector();break;case 'edit-section':editSection(page,i);break;case 'add-section':{const p=el.dataset.page||selectedPage;modal('Create page section',`<div class="form-grid">${input('Section title','New section')}${select('Section type',[['custom','Text / media / custom'],['articleStack','Featured articles'],['featured','Featured works'],['summary','Professional summary'],['worksGrid','Works grid'],['articleGallery','Article gallery']], 'custom')}</div>`,v=>update(()=>state.sections[p].push(section(v['Section type'],v['Section title'])),{rerender:false}));break}case 'section-up':case 'section-down':{const arr=state.sections[page],j=i+(action==='section-up'?-1:1);if(j>=0&&j<arr.length)update(()=>[arr[i],arr[j]]=[arr[j],arr[i]]);break}case 'duplicate-section':update(()=>{const s=clone(state.sections[page][i]);s.id=id();state.sections[page].splice(i+1,0,s)});break;case 'delete-section':if(confirm('Delete this section?'))update(()=>state.sections[page].splice(i,1));break;case 'article-block-add':update(()=>state.articles[i].blocks.push({id:id(),columns:1,items:[[block('text')]]}));break;case 'article-block-up':case 'article-block-down':{const arr=state.articles[ai].blocks,j=bi+(action==='article-block-up'?-1:1);if(j>=0&&j<arr.length)update(()=>[arr[bi],arr[j]]=[arr[j],arr[bi]]);break}case 'article-block-remove':if(confirm('Remove this article section?'))update(()=>state.articles[ai].blocks.splice(bi,1));break;case 'article-cols':articleCols(ai,bi);break;case 'add-article-item':chooseArticleItem(ai,bi,ci);break;case 'format-item':articleItemStyle(ai,bi,ci,ii);break;case 'rich-bold':case 'rich-underline':case 'rich-italic':{const target=el.closest('.article-element')?.querySelector('[contenteditable]');if(target){document.execCommand(action.replace('rich-',''),false);const item=locationItem(ai,bi,ci,ii);item.html=target.innerHTML;persist()}break}case 'change-item-file':(async()=>{const m=await selectMedia(locationItem(ai,bi,ci,ii));if(m)update(()=>Object.assign(locationItem(ai,bi,ci,ii),m))})();break;case 'remove-item':update(()=>state.articles[ai].blocks[bi].items[ci].splice(ii,1));break;case 'move-item-up':case 'move-item-down':{const arr=state.articles[ai].blocks[bi].items[ci],j=ii+(action==='move-item-up'?-1:1);if(j>=0&&j<arr.length)update(()=>[arr[ii],arr[j]]=[arr[j],arr[ii]]);break}}
}
// Event delegation allows the editor to survive complete page re-renders.
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-action^=rich-]'))e.preventDefault()});
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(btn){if(btn.tagName==='A')e.preventDefault();onAction(btn)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modalLayer').hidden)closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=link][data-action]')){e.preventDefault();onAction(e.target)}});
$('#editBtn').addEventListener('click',beginEdit);$('#themeBtn').addEventListener('click',()=>update(()=>state.settings.theme=state.settings.theme==='light'?'dark':'light'));
$('#menuBtn').addEventListener('click',()=>$('#nav').classList.toggle('open'));
let dragId=null;document.addEventListener('dragstart',e=>{if(!editing)return;const m=e.target.closest('.module[data-section]');if(m){dragId=m.dataset.section;e.dataTransfer.effectAllowed='move'}});document.addEventListener('dragover',e=>{if(dragId&&e.target.closest('.module'))e.preventDefault()});document.addEventListener('drop',e=>{const m=e.target.closest('.module');if(!m||!dragId)return;e.preventDefault();const sections=state.sections[selectedPage],old=sections.findIndex(s=>s.id===dragId),target=sections.findIndex(s=>s.id===m.dataset.section);if(old>=0&&target>=0&&old!==target)update(()=>sections.splice(target,0,sections.splice(old,1)[0]));dragId=null});document.addEventListener('dragend',()=>dragId=null);
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#nav').classList.remove('open')});
window.addEventListener('pointermove',e=>{if(matchMedia('(hover:hover) and (pointer:fine)').matches){const g=$('#cursorGlow');g.style.transform=`translate(${e.clientX-19}px,${e.clientY-19}px)`}});
const priorRender=render;render=function(){priorRender();bindInlineChanges()};
render();hydrate();
})();
